struct BoneList
{
    std::uint8_t indices[256]{};
    std::uint32_t count{};
    std::uint32_t membership[8]{};
};
static_assert(sizeof(BoneList) == 292 && offsetof(BoneList,membership) == 260);
constexpr BoneList AllBones(unsigned count)
{
    BoneList result{};
    result.count = count;
    for (unsigned i = 0; i != count; ++i)
    {
        result.indices[i] = static_cast<std::uint8_t>(i);
        result.membership[i/32] |= 1u << (i%32);
    }
    return result;
}
// One authored rig profile. The target side is rig-specific; the source side is
// shared because every rig merges the same 190-bone slide source model.
struct Profile
{
    std::string_view marker;
    std::size_t targetCount;
    const Bone* targetBones;
    const float (*targetPoseToBone)[12];
    const Mapping* mappings;
    BoneList fullTarget;
    unsigned poseCount;
    const unsigned (*chainLinks)[3];
};
constexpr unsigned MaleChainLinks[2][3]={{38,42,44},{14,18,20}};
constexpr unsigned FemaleChainLinks[2][3]={{42,46,48},{13,17,19}};
constexpr Profile MaleProfile{"pilot_slide_190_223",MaleTargetBoneCount,MaleTargetBones,
    MaleTargetPoseToBone,MaleMappings,AllBones(MaleTargetBoneCount),8,MaleChainLinks};
constexpr Profile FemaleProfile{"pilot_slide_190_228",FemaleTargetBoneCount,FemaleTargetBones,
    FemaleTargetPoseToBone,FemaleMappings,AllBones(FemaleTargetBoneCount),7,FemaleChainLinks};
// Both rigs merge the same 190-bone slide source rig, whose own hand chains are shared.
constexpr unsigned SourceChainLinks[2][3]{{12,18,23},{10,16,21}};
constexpr BoneList FullSource = AllBones(SourceBoneCount);

Matrix Multiply(const Matrix& a, const Matrix& b)
{
    Matrix result{};
    for (unsigned row = 0; row != 3; ++row)
        for (unsigned col = 0; col != 4; ++col)
        {
            double value = col == 3 ? a.m[row * 4 + 3] : 0;
            for (unsigned k = 0; k != 3; ++k)
                value += a.m[row * 4 + k] * b.m[k * 4 + col];
            if (!std::isfinite(value)) Fail("nonfinite composed transform");
            result.m[row * 4 + col] = value;
        }
    return result;
}
double Determinant(const Matrix& a)
{
    return a.m[0] * (a.m[5] * a.m[10] - a.m[6] * a.m[9])
        - a.m[1] * (a.m[4] * a.m[10] - a.m[6] * a.m[8])
        + a.m[2] * (a.m[4] * a.m[9] - a.m[5] * a.m[8]);
}
Matrix Inverse(const Matrix& a)
{
    const double det = Determinant(a);
    if (!std::isfinite(det) || std::abs(det) <= 1e-12)
        Fail("singular parent transform");
    Matrix result{{
        a.m[5]*a.m[10]-a.m[6]*a.m[9], a.m[2]*a.m[9]-a.m[1]*a.m[10], a.m[1]*a.m[6]-a.m[2]*a.m[5], 0,
        a.m[6]*a.m[8]-a.m[4]*a.m[10], a.m[0]*a.m[10]-a.m[2]*a.m[8], a.m[2]*a.m[4]-a.m[0]*a.m[6], 0,
        a.m[4]*a.m[9]-a.m[5]*a.m[8], a.m[1]*a.m[8]-a.m[0]*a.m[9], a.m[0]*a.m[5]-a.m[1]*a.m[4], 0}};
    for (unsigned row = 0; row != 3; ++row)
    {
        for (unsigned col = 0; col != 3; ++col)
        {
            result.m[row * 4 + col] /= det;
            result.m[row * 4 + 3] -= result.m[row * 4 + col] * a.m[col * 4 + 3];
        }
    }
    return result;
}
Matrix TransformMatrix(const LocalTransform& transform)
{
    double q[4];
    double length = 0;
    for (unsigned i = 0; i != 4; ++i)
    {
        q[i] = transform.quaternion[i];
        length += q[i] * q[i];
    }
    if (!std::isfinite(length) || length <= 1e-24)
        Fail("invalid completed-pose quaternion");
    length = std::sqrt(length);
    for (double& value : q) value /= length;
    const double x=q[0], y=q[1], z=q[2], w=q[3];
    Matrix result{{1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), 0,
        2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), 0,
        2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), 0}};
    for (unsigned row = 0; row != 3; ++row)
    {
        if (!std::isfinite(transform.position[row])
            || !std::isfinite(transform.scale[row])
            || std::abs(transform.scale[row]) <= 1e-12)
            Fail("invalid completed-pose position or scale");
        result.m[row * 4 + 3] = transform.position[row];
        for (unsigned col = 0; col != 3; ++col)
            result.m[row * 4 + col] *= transform.scale[col];
    }
    return result;
}
LocalTransform Decompose(const Matrix& a, const LocalTransform& reference)
{
    double scale[3], r[9];
    for (unsigned col = 0; col != 3; ++col)
    {
        scale[col] = std::sqrt(a.m[col]*a.m[col] + a.m[4+col]*a.m[4+col] + a.m[8+col]*a.m[8+col]);
        if (!std::isfinite(scale[col]) || scale[col] <= 1e-12)
            Fail("unrepresentable zero-scale target transform");
    }
    // Preserve reflection parity instead of dropping a signed scale.
    if (Determinant(a) < 0) scale[0] = -scale[0];
    for (unsigned row = 0; row != 3; ++row)
        for (unsigned col = 0; col != 3; ++col)
            r[row * 3 + col] = a.m[row * 4 + col] / scale[col];
    double q[4]{};
    const double trace = r[0] + r[4] + r[8];
    if (trace > 0)
    {
        const double s = std::sqrt(trace + 1) * 2;
        q[0]=(r[7]-r[5])/s; q[1]=(r[2]-r[6])/s; q[2]=(r[3]-r[1])/s; q[3]=s/4;
    }
    else
    {
        unsigned axis = 0;
        if (r[4] > r[0]) axis = 1;
        if (r[8] > r[axis * 3 + axis]) axis = 2;
        const unsigned j = (axis + 1) % 3, k = (axis + 2) % 3;
        const double square = 1+r[axis*3+axis]-r[j*3+j]-r[k*3+k];
        if (!(square > 0)) Fail("unrepresentable target rotation");
        const double s = std::sqrt(square) * 2;
        q[axis]=s/4; q[j]=(r[axis*3+j]+r[j*3+axis])/s;
        q[k]=(r[axis*3+k]+r[k*3+axis])/s; q[3]=(r[k*3+j]-r[j*3+k])/s;
    }
    double length = 0, dot = 0;
    for (unsigned i = 0; i != 4; ++i)
    {
        length += q[i]*q[i];
        dot += q[i]*reference.quaternion[i];
    }
    if (!std::isfinite(length) || length <= 1e-24)
        Fail("unrepresentable target quaternion");
    length = std::sqrt(length) * (dot < 0 ? -1 : 1);
    LocalTransform result{};
    for (unsigned i = 0; i != 3; ++i)
    {
        result.position[i] = static_cast<float>(a.m[i*4+3]);
        result.scale[i] = static_cast<float>(scale[i]);
    }
    for (unsigned i = 0; i != 4; ++i)
        result.quaternion[i] = static_cast<float>(q[i] / length);
    const Matrix rebuilt = TransformMatrix(result);
    // Shear is a property of the linear 3x3 transform, not its translation.
    // Position is already rounded to native float32 above and checked finite by
    // TransformMatrix; a fixed absolute translation tolerance rejects valid poses
    // once float32 spacing exceeds it. Keep the authored shear check unchanged.
    for (unsigned row = 0; row != 3; ++row)
        for (unsigned col = 0; col != 3; ++col)
            if (std::abs(rebuilt.m[row * 4 + col] - a.m[row * 4 + col]) > 0.00001)
                Fail("authored affine transform is not representable by native TRS");
    return result;
}

// Pose math runs only while the module mutex is held (every entry point is inside an admitted
// Invocation), so one static workspace serves all evaluations without per-frame allocation.
// The target channels are staged here so a rejected retarget leaves the native pose untouched.
struct Scratch
{
    Matrix source[SourceBoneCount];
    Matrix target[TargetBoneCapacity];
    Matrix desired[SourceBoneCount];
    std::uint8_t sourceState[SourceBoneCount];
    std::uint8_t targetState[TargetBoneCapacity];
    int reverse[TargetBoneCapacity];
    float position[TargetBoneCapacity][3];
    alignas(16) float quaternion[TargetBoneCapacity][4];
    float scale[TargetBoneCapacity][3];
};
Scratch g_scratch;
void ResetScratch(Scratch& scratch)
{
    std::memset(scratch.sourceState, 0, sizeof(scratch.sourceState));
    std::memset(scratch.targetState, 0, sizeof(scratch.targetState));
    for (int& index : scratch.reverse) index = -1;
}

const Matrix& ComposeWorld(std::size_t bone, ConstPoseChannels local,
    const Bone* bones, std::size_t count, Matrix* world, std::uint8_t* state)
{
    if (state[bone] == 2) return world[bone];
    if (state[bone]) Fail("cyclic pose hierarchy");
    state[bone] = 1;
    const int parent = bones[bone].parent;
    if (parent < -1 || parent >= static_cast<int>(count)
        || parent == static_cast<int>(bone)) Fail("invalid pose hierarchy");
    const Matrix transform = TransformMatrix(ReadTransform(local,bone));
    world[bone] = parent < 0 ? transform : Multiply(
        ComposeWorld(parent,local,bones,count,world,state),transform);
    state[bone] = 2;
    return world[bone];
}
const Matrix& TargetWorld(std::size_t bone, PoseChannels target, Scratch& scratch,
    const Profile& profile)
{
    if (scratch.targetState[bone] == 2) return scratch.target[bone];
    if (scratch.targetState[bone]) Fail("cyclic target hierarchy");
    scratch.targetState[bone] = 1;
    const int parent = profile.targetBones[bone].parent;
    if (parent < -1 || parent >= static_cast<int>(profile.targetCount)
        || parent == static_cast<int>(bone)) Fail("invalid target hierarchy");
    const Matrix& parentWorld = parent < 0 ? Identity : TargetWorld(parent,target,scratch,profile);
    const int source = scratch.reverse[bone];
    if (source >= 0)
        WriteTransform(target,bone,Decompose(Multiply(Inverse(parentWorld),
            scratch.desired[source]),ReadTransform(target,bone)));
    // Native-only facial/origin channels are never written, including scale.
    scratch.target[bone] = Multiply(parentWorld,TransformMatrix(ReadTransform(target,bone)));
    scratch.targetState[bone] = 2;
    return scratch.target[bone];
}
const Matrix& ImportSourceWorld(std::size_t bone, PoseChannels source, Scratch& scratch)
{
    if (scratch.sourceState[bone] == 2) return scratch.source[bone];
    if (scratch.sourceState[bone]) Fail("cyclic source hierarchy during native import");
    scratch.sourceState[bone] = 1;
    const int parent = SourceBones[bone].parent;
    if (parent < -1 || parent >= static_cast<int>(SourceBoneCount)
        || parent == static_cast<int>(bone)) Fail("invalid source hierarchy during native import");
    const Matrix& parentWorld = parent < 0 ? Identity : ImportSourceWorld(parent,source,scratch);
    WriteTransform(source,bone,Decompose(Multiply(Inverse(parentWorld),
        scratch.desired[bone]),ReadTransform(source,bone)));
    scratch.source[bone] = Multiply(parentWorld,TransformMatrix(ReadTransform(source,bone)));
    scratch.sourceState[bone] = 2;
    return scratch.source[bone];
}

class ModelView
{
public:
    ModelView(const void* data, std::size_t available) : bytes(static_cast<const std::uint8_t*>(data)), length(available)
    {
        if (!bytes || available < 408 || Read<std::uint32_t>(0) != 0x54534449 || Read<int>(4) != 52)
            Fail("pose model is not a complete native studio52 header");
        const int declared = Read<int>(76);
        if (declared < 408 || static_cast<std::size_t>(declared) > available)
            Fail("truncated pose model");
        length = static_cast<std::size_t>(declared);
    }
    template<typename T> T Read(std::size_t offset) const
    {
        if (offset > length || sizeof(T) > length-offset) Fail("pose model field exceeds studio bounds");
        T result;
        std::memcpy(&result,bytes+offset,sizeof(result));
        return result;
    }
    std::size_t Size() const { return length; }
    const std::uint8_t* Data() const { return bytes; }
    const std::uint8_t* Span(std::int64_t at, std::size_t count, std::size_t stride = 1) const
    {
        if (at < 0 || static_cast<std::uint64_t>(at) > length
            || !stride || count > (length-static_cast<std::size_t>(at))/stride)
            Fail("pose model relative stream exceeds studio bounds");
        return bytes+at;
    }
    std::string_view String(std::int64_t at) const
    {
        const auto* begin = reinterpret_cast<const char*>(Span(at,1));
        const auto* end = static_cast<const char*>(std::memchr(begin,0,length-static_cast<std::size_t>(at)));
        if (!end) Fail("unterminated pose model string");
        return {begin,static_cast<std::size_t>(end-begin)};
    }
    std::string_view RelativeString(std::size_t at, std::size_t field = 0) const
    {
        return String(static_cast<std::int64_t>(at)+Read<int>(at+field));
    }
    void Validate(const Bone* bones, std::size_t count, const float (*poseToBone)[12]) const
    {
        if (Read<int>(156) != static_cast<int>(count)) Fail("pose model bone count differs from authored mapping");
        const int offset = Read<int>(160);
        if (offset < 408 || static_cast<std::size_t>(offset) > length
            || count > (length-static_cast<std::size_t>(offset))/216)
            Fail("pose model bone table exceeds studio bounds");
        for (std::size_t i = 0; i != count; ++i)
        {
            const std::size_t at = static_cast<std::size_t>(offset) + i*216;
            const std::int64_t nameAt = static_cast<std::int64_t>(at) + Read<int>(at);
            const std::size_t nameLength = std::strlen(bones[i].name) + 1;
            if (nameAt < 0 || static_cast<std::uint64_t>(nameAt) > length
                || nameLength > length-static_cast<std::size_t>(nameAt)
                || std::memcmp(bytes+nameAt,bones[i].name,nameLength))
                Fail("pose model bone name or ordering differs from authored mapping");
            if (Read<int>(at+4) != bones[i].parent)
                Fail("pose model hierarchy differs from authored mapping");
            for (unsigned k = 0; k != 3; ++k)
            {
                Match(Read<float>(at+32+k*4),bones[i].bind.position[k]);
                Match(Read<float>(at+188+k*4),bones[i].bind.scale[k]);
            }
            for (unsigned k = 0; k != 4; ++k)
                Match(Read<float>(at+44+k*4),bones[i].bind.quaternion[k]);
            if (poseToBone)
                for (unsigned k = 0; k != 12; ++k)
                    Match(Read<float>(at+96+k*4),poseToBone[i][k]);
        }
    }
private:
    static void Match(float actual, float expected)
    {
        if (!std::isfinite(actual) || actual != expected)
            Fail("pose model bind channels differ from authored mapping");
    }
    const std::uint8_t* bytes;
    std::size_t length;
};

// Both functions stage/consume channels through g_scratch and therefore require the module mutex.
void RetargetCompletePose(const Profile& profile, ConstPoseChannels source, PoseChannels target)
{
    ValidateChannels(source);
    ValidateChannels(target);
    Scratch& scratch = g_scratch;
    ResetScratch(scratch);
    const std::size_t count = profile.targetCount;
    if (count > TargetBoneCapacity) Fail("authored target rig exceeds the native pose capacity");
    std::memcpy(scratch.position, target.position, count * sizeof(scratch.position[0]));
    std::memcpy(scratch.quaternion, target.quaternion, count * sizeof(scratch.quaternion[0]));
    std::memcpy(scratch.scale, target.scale, count * sizeof(scratch.scale[0]));
    const PoseChannels staged{scratch.position, scratch.quaternion, scratch.scale};
    for (std::size_t i = 0; i != SourceBoneCount; ++i)
    {
        const int targetIndex = profile.mappings[i].target;
        if (targetIndex < 0 || targetIndex >= static_cast<int>(count) || scratch.reverse[targetIndex] >= 0)
            Fail("incomplete or duplicated authored source-to-target mapping");
        scratch.reverse[targetIndex] = static_cast<int>(i);
        scratch.desired[i] = Multiply(ComposeWorld(i,source,SourceBones,SourceBoneCount,
            scratch.source,scratch.sourceState),profile.mappings[i].correction);
    }
    for (std::size_t i = 0; i != count; ++i) TargetWorld(i,staged,scratch,profile);
    for (std::size_t i = 0; i != SourceBoneCount; ++i)
        for (unsigned k = 0; k != 12; ++k)
            if (std::abs(scratch.target[profile.mappings[i].target].m[k]-scratch.desired[i].m[k]) > 0.002)
                Fail("localized target pose exceeds authored world-space reconstruction bound");
    // Commit only a fully reconstructed pose. Native-only channels were staged unchanged.
    std::memcpy(target.position, scratch.position, count * sizeof(scratch.position[0]));
    std::memcpy(target.quaternion, scratch.quaternion, count * sizeof(scratch.quaternion[0]));
    std::memcpy(target.scale, scratch.scale, count * sizeof(scratch.scale[0]));
}

void ImportNativePose(const Profile& profile, ConstPoseChannels target, PoseChannels source)
{
    ValidateChannels(target);
    ValidateChannels(source);
    Scratch& scratch = g_scratch;
    ResetScratch(scratch);
    for (std::size_t i = 0; i != SourceBoneCount; ++i)
        scratch.desired[i] = Multiply(ComposeWorld(profile.mappings[i].target,target,
            profile.targetBones,profile.targetCount,scratch.target,scratch.targetState),
            Inverse(profile.mappings[i].correction));
    for (std::size_t i = 0; i != SourceBoneCount; ++i) ImportSourceWorld(i,source,scratch);
    for (std::size_t i = 0; i != SourceBoneCount; ++i)
        for (unsigned k = 0; k != 12; ++k)
            if (std::abs(scratch.source[i].m[k]-scratch.desired[i].m[k]) > 0.002)
                Fail("native contribution import exceeds authored world-space reconstruction bound");
}

