// The only models owned by this module: the nine transferred MP pilot roots. Everything else
// is rejected by FindRoot before any parsing, locking or allocation.
struct RootModel
{
    const char* name;
    const Profile* profile;
    std::size_t length;
};
constexpr RootModel MakeRoot(const char* name, const Profile* profile)
{
    return {name, profile, std::char_traits<char>::length(name)};
}
constexpr RootModel kRoots[] = {
    MakeRoot("humans/imc_pilot/male_br/imc_pilot_male_br.mdl", &MaleProfile),
    MakeRoot("humans/imc_pilot/male_dm/imc_pilot_male_dm.mdl", &MaleProfile),
    MakeRoot("humans/mcor_pilot/male_br/mcor_pilot_male_br.mdl", &MaleProfile),
    MakeRoot("humans/mcor_pilot/male_dm/mcor_pilot_male_dm.mdl", &MaleProfile),
    MakeRoot("humans/pilot/female_br/pilot_female_br.mdl", &FemaleProfile),
    MakeRoot("humans/pilot/female_dm/pilot_female_dm.mdl", &FemaleProfile),
};
// Playtest: the three *_cq models (imc/mcor male, female) are deliberately NOT retargeted: the pose retarget made the CQB pilot invisible,
// so those models keep their native animation (no authored slide animation for CQB).
static_assert(std::size(kRoots) == 6);

template<class T> T At(const void* object, std::size_t offset)
{
    T value;
    std::memcpy(&value,static_cast<const std::byte*>(object)+offset,sizeof(value));
    return value;
}
template<class T> T At(std::uintptr_t object, std::size_t offset)
{
    return At<T>(reinterpret_cast<const void*>(object),offset);
}

// Zero-work classifier for a native studio header: a few loads and one prefix compare reject
// every stock/other model (including non-studio52 content).
const RootModel* FindRoot(std::uintptr_t raw) noexcept
{
    if (!raw) return nullptr;
    const auto* bytes = reinterpret_cast<const std::uint8_t*>(raw);
    std::uint32_t id;
    std::int32_t version, length;
    std::memcpy(&id, bytes, sizeof(id));
    std::memcpy(&version, bytes + 4, sizeof(version));
    std::memcpy(&length, bytes + 76, sizeof(length));
    if (id != 0x54534449 || version != 52 || length < 408) return nullptr;
    const auto* name = reinterpret_cast<const char*>(bytes + 12);
    if (std::memcmp(name, "humans/", 7)) return nullptr;
    for (const auto& root : kRoots)
        if (std::memcmp(name, root.name, root.length + 1) == 0) return &root;
    return nullptr;
}
const RootModel* FindRootForStudio(std::uintptr_t studio) noexcept
{
    return studio ? FindRoot(At<std::uintptr_t>(studio,8)) : nullptr;
}

ModelView RawModel(std::uintptr_t raw)
{
    if (!raw) Fail("native studio header is absent");
    const int size = At<int>(raw,76);
    if (size < 408) Fail("native studio header has an invalid length");
    return ModelView(reinterpret_cast<const void*>(raw),static_cast<std::size_t>(size));
}
std::string_view ModelName(const ModelView& model)
{
    const auto* name = reinterpret_cast<const char*>(model.Span(12,64));
    const auto* end = static_cast<const char*>(std::memchr(name,0,64));
    if (!end) Fail("unterminated native model name");
    return {name,static_cast<std::size_t>(end-name)};
}

struct Tokens
{
    std::string_view input;
    std::size_t cursor{};
    std::string_view Next()
    {
        for (;;)
        {
            while (cursor < input.size() && static_cast<unsigned char>(input[cursor]) <= ' ') ++cursor;
            if (cursor+1 < input.size() && input[cursor] == '/' && input[cursor+1] == '/')
            {
                while (cursor < input.size() && input[cursor] != '\n') ++cursor;
                continue;
            }
            break;
        }
        if (cursor == input.size()) return {};
        const auto begin = cursor++;
        if (input[begin] == '{' || input[begin] == '}') return input.substr(begin,1);
        if (input[begin] == '"')
        {
            while (cursor < input.size() && input[cursor] != '"')
            {
                if (input[cursor] == '\\' && cursor+1 < input.size()) ++cursor;
                ++cursor;
            }
            if (cursor == input.size()) Fail("unterminated pose keyvalue token");
            return input.substr(begin+1,cursor++-begin-1);
        }
        while (cursor < input.size() && static_cast<unsigned char>(input[cursor]) > ' '
            && input[cursor] != '{' && input[cursor] != '}') ++cursor;
        return input.substr(begin,cursor-begin);
    }
};
// Returns the authored profile named by the unique root r1delta_player_pose block, or null when the
// header carries no such block. Other root keyvalue blocks stay opaque.
const Profile* Marker(const ModelView& model)
{
    const int offset = model.Read<int>(312), size = model.Read<int>(316);
    if (size == 0) return nullptr;
    if (size < 0) Fail("invalid bounded pose keyvalues size");
    const auto* bytes = reinterpret_cast<const char*>(model.Span(offset,static_cast<std::size_t>(size)));
    if (bytes[size-1] || std::memchr(bytes,0,size-1)) Fail("invalid pose keyvalues terminator");
    Tokens tokens{{bytes,static_cast<std::size_t>(size-1)}};
    const Profile* profile = nullptr;
    unsigned depth = 0;
    while (tokens.cursor < tokens.input.size())
    {
        const auto token = tokens.Next();
        if (token == "{") { ++depth; continue; }
        if (token == "}")
        {
            if (!depth) Fail("unbalanced pose keyvalues");
            --depth;
            continue;
        }
        if (token != "r1delta_player_pose") continue;
        if (depth || profile) Fail("pose marker must be a unique root block");
        if (tokens.Next() != "{" || tokens.Next() != "version" || tokens.Next() != "1"
            || tokens.Next() != "profile") Fail("unsupported required player pose marker");
        const auto marker = tokens.Next();
        if ((marker != MaleProfile.marker && marker != FemaleProfile.marker)
            || tokens.Next() != "source_sha256" || tokens.Next() != PilotSourceModelSha256
            || tokens.Next() != "include_sha256" || tokens.Next() != PilotIncludeModelSha256
            || tokens.Next() != "}") Fail("unsupported required player pose marker");
        profile = marker == MaleProfile.marker ? &MaleProfile : &FemaleProfile;
    }
    if (depth) Fail("unbalanced pose keyvalues");
    return profile;
}

using Digest = std::array<unsigned char,32>;
Digest Hash(const void* data, std::size_t size)
{
    if (size > (std::numeric_limits<ULONG>::max)()) Fail("pose SHA256 input exceeds BCrypt length");
    BCRYPT_ALG_HANDLE algorithm{};
    if (BCryptOpenAlgorithmProvider(&algorithm,BCRYPT_SHA256_ALGORITHM,nullptr,0) < 0)
        Unavailable("cannot initialize pose SHA256 verification");
    Digest result{};
    const auto status = BCryptHash(algorithm,nullptr,0,
        const_cast<PUCHAR>(static_cast<const unsigned char*>(data)),static_cast<ULONG>(size),
        result.data(),static_cast<ULONG>(result.size()));
    BCryptCloseAlgorithmProvider(algorithm,0);
    if (status < 0) Unavailable("pose SHA256 operation failed");
    return result;
}
Digest ParseDigest(std::string_view text)
{
    if (text.size() != 64) Fail("invalid pose SHA256 length");
    Digest result{};
    for (std::size_t i = 0; i != text.size(); ++i)
    {
        const char c = text[i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')))
            Fail("invalid lowercase pose SHA256");
        result[i/2] = static_cast<unsigned char>((result[i/2]<<4)|(c <= '9' ? c-'0' : c-'a'+10));
    }
    return result;
}

// Reads one asset through the native GAME search paths (loose files, mounted VPKs and addons).
std::vector<std::byte> ReadGameAsset(const char* path, unsigned minimumBytes, unsigned maximumBytes)
{
    if (!path || !*path || minimumBytes > maximumBytes || maximumBytes > INT_MAX)
        Fail("invalid native asset read request");
    if (!g_CBaseFileSystem || !g_CBaseFileSystemInterface
        || !g_CBaseFileSystem->Open || !g_CBaseFileSystem->Size2
        || !g_CBaseFileSystem->Read || !g_CBaseFileSystem->Close)
        Unavailable("native GAME filesystem is not initialized");
    using Open = void*(__fastcall*)(void*, const char*, const char*, const char*);
    using Size = std::int64_t(__fastcall*)(void*, void*);
    using Read = int(__fastcall*)(void*, void*, int, void*);
    using Close = void(__fastcall*)(void*, void*);
    void* self = g_CBaseFileSystemInterface;
    void* file = reinterpret_cast<Open>(g_CBaseFileSystem->Open)(self, path, "rb", "GAME");
    if (!file) Unavailable("required slide asset is missing from the native GAME search paths");
    const auto size = reinterpret_cast<Size>(g_CBaseFileSystem->Size2)(self, file);
    if (size < static_cast<std::int64_t>(minimumBytes) || size > static_cast<std::int64_t>(maximumBytes))
    {
        reinterpret_cast<Close>(g_CBaseFileSystem->Close)(self, file);
        Fail("native slide asset has an invalid size");
    }
    std::vector<std::byte> bytes(static_cast<std::size_t>(size));
    const int count = reinterpret_cast<Read>(g_CBaseFileSystem->Read)(self, bytes.data(), static_cast<int>(size), file);
    reinterpret_cast<Close>(g_CBaseFileSystem->Close)(self, file);
    if (count != static_cast<int>(size)) Unavailable("short read of required slide asset");
    return bytes;
}
std::vector<std::byte> ReadPinned(const char* path, const char* hash)
{
    auto bytes = ReadGameAsset(path,408,64u*1024u*1024u);
    if (Hash(bytes.data(),bytes.size()) != ParseDigest(hash))
        Fail("required slide GAME asset differs from pinned SHA256");
    if (ModelView(bytes.data(),bytes.size()).Size() != bytes.size())
        Fail("slide asset contains bytes outside its declared studio length");
    return bytes;
}

struct NativeSetup
{
    std::uintptr_t header;
    const BoneList* bones;
    std::byte cache[1280];
    int cacheCount;
    std::uint32_t padding;
    float* poses;
    void* observer;
    std::uint8_t face, skip;
    std::byte tail[6];
};
static_assert(sizeof(NativeSetup) == 1328 && offsetof(NativeSetup,cacheCount) == 1296
    && offsetof(NativeSetup,poses) == 1304 && offsetof(NativeSetup,observer) == 1312
    && offsetof(NativeSetup,face) == 1320);
using Accumulate = void(__fastcall*)(void*,void*,void*,void*,int,float,float,float,void*);
using ClientOuter = void(__fastcall*)(std::uintptr_t,std::uintptr_t,void*,void*,void*,float,const BoneList*);
using ServerOuter = void(__fastcall*)(std::uintptr_t,std::uintptr_t,void*,void*,void*,const BoneList*);
using ClientBoundary = void(__fastcall*)(std::uintptr_t,void*,void*,void*,void*,float);
using ServerBoundary = void(__fastcall*)(std::uintptr_t,void*,void*,void*,void*);

enum class Side : unsigned { Client, Server };
// Client RVAs (R1 client.dll SHA-256 5b3f0080...).
constexpr std::uintptr_t kOuterRva = 0x06EF50;
constexpr std::uintptr_t kBoundaryRva = 0x0715D0;
constexpr std::uintptr_t kAccumulateRva = 0x56F970;
constexpr std::uintptr_t kSourceConstructRva = 0x272350;
constexpr std::uintptr_t kSourceDestroyRva = 0x017BA0;
constexpr std::uintptr_t kSetupDestroyRva = 0x56E210;
constexpr std::uintptr_t kSetupConstructRva = 0x56C530;
constexpr std::uintptr_t kSequenceRva = 0x010230;
constexpr std::uintptr_t kPoseCountRva = 0x26C1F0;
constexpr std::uintptr_t kPoseDescriptorRva = 0x26D5F0;
constexpr std::uintptr_t kPitchNormalizeRva = 0x55D4E0;
constexpr std::uintptr_t kIkRegisterRva = 0x56B5A0;
constexpr std::uintptr_t kPlayerPredicateRva = 0x037420;
constexpr std::uintptr_t kScheduledReturnA = 0x06F1DB;
constexpr std::uintptr_t kScheduledReturnB = 0x01640B;
constexpr std::uintptr_t kBoundaryReturn = 0x06F22B;
constexpr std::size_t kBoundaryVtableOffset = 0x6E0;
constexpr std::size_t kPlayerStudioOffset = 8856;

// Server RVAs (R1 server.dll SHA-256 50faad92...).
constexpr std::uintptr_t kServerOuterRva = 0x09A8A0;
constexpr std::uintptr_t kServerBoundaryRva = 0x098950;
constexpr std::uintptr_t kServerAccumulateRva = 0x63DAD0;
constexpr std::uintptr_t kServerSourceHeaderInitRva = 0x20FC00;
constexpr std::uintptr_t kServerSourceConstructRva = 0x20FD60;
constexpr std::uintptr_t kServerSourceDestroyRva = 0x081780;
constexpr std::uintptr_t kServerSetupDestroyRva = 0x63DA40;
constexpr std::uintptr_t kServerSetupConstructRva = 0x63C510;
constexpr std::uintptr_t kServerSequenceRva = 0x07FF30;
constexpr std::uintptr_t kServerPoseCountRva = 0x2100F0;
constexpr std::uintptr_t kServerPoseDescriptorRva = 0x210120;
constexpr std::uintptr_t kServerPitchNormalizeRva = 0x639F00;
constexpr std::uintptr_t kServerIkRegisterRva = 0x640EA0;
constexpr std::uintptr_t kServerPlayerPredicateRva = 0x41CDA0;
constexpr std::uintptr_t kServerScheduledReturnA = 0x09A9CB;
constexpr std::uintptr_t kServerScheduledReturnB = 0x098B6A;
constexpr std::uintptr_t kServerBoundaryReturn = 0x09AA03;
// R1 server player ABI: CBaseEntity IsPlayer/IsTitan virtual slots and player studio-header offset.
constexpr std::size_t kServerPlayerVtableIsPlayerOffset = 0x2B0;
constexpr std::size_t kServerPlayerVtableIsTitanOffset = 0x2B8;
constexpr std::size_t kServerPlayerStudioOffset = 2584;

struct ModelIdentity
{
    std::uint32_t owner{};
    std::uintptr_t player{}, studio{}, raw{}, virtualModel{};
    std::uint32_t checksum{};
    int length{}, sequences{}, groups{};
    bool operator==(const ModelIdentity& other) const noexcept
    {
        return owner == other.owner && player == other.player && studio == other.studio
            && raw == other.raw && virtualModel == other.virtualModel && checksum == other.checksum
            && length == other.length && sequences == other.sequences && groups == other.groups;
    }
};
// Everything derived from one admitted native model. Scoped to the install session and to the
// model generation (header/virtual-model identity); a differing identity re-admits from scratch.
struct PoseClosure
{
    ModelIdentity model;
    std::uint64_t session{}, generation{};
    const Profile* profile{};
    bool admitted{}, disabled{};
    std::vector<int> sourceSequence;
    int sourceGroup{-1}, poseIndices[2]{-1,-1};
};
enum class AssetState { Unloaded, Ready, Rejected };
// Retarget math uses one static scratch workspace, so both native sides share its lock.
std::recursive_mutex gPoseMutex;
struct State
{
    explicit State(Side imageSide) noexcept : side(imageSide), mutex(gPoseMutex) {}
    Side side;
    std::recursive_mutex& mutex;
    std::atomic<bool> ready{false};
    std::atomic<unsigned> frames{0};
    bool hooksInstalled{};
    std::uintptr_t base{};
    std::uint64_t session{}, generation{};
    Accumulate accumulate{};
    void* outer{};
    void* boundary{};
    AssetState assets{AssetState::Unloaded};
    ULONGLONG assetRetryAt{};
    alignas(16) std::byte sourceHeader[200]{};
    std::vector<std::byte> sourceBytes, includeBytes;
    bool sourceConstructed{};
    std::unordered_map<std::uintptr_t,PoseClosure> closures;
};
State gClient{Side::Client};
State gServer{Side::Server};
thread_local State* t_activeState{};
State& CurrentState() noexcept { return t_activeState ? *t_activeState : gClient; }
class StateScope
{
    State* previous;
public:
    explicit StateScope(State& state) noexcept : previous(t_activeState) { t_activeState = &state; }
    ~StateScope() { t_activeState = previous; }
    StateScope(const StateScope&) = delete;
    StateScope& operator=(const StateScope&) = delete;
};

struct RvaPair { std::uintptr_t client, server; };
template<class R, class... A> R Call(RvaPair rvas, A... arguments)
{
    const auto rva = CurrentState().side == Side::Client ? rvas.client : rvas.server;
    return reinterpret_cast<R(__fastcall*)(A...)>(CurrentState().base+rva)(arguments...);
}

ModelIdentity CurrentModel(std::uintptr_t player)
{
    ModelIdentity identity;
    const auto table = player ? At<std::uintptr_t>(player,0) : 0;
    const auto handleOf = table ? At<std::uintptr_t>(table,16) : 0;
    if (!handleOf) return identity;
    const auto* owner = reinterpret_cast<const std::uint32_t*(__fastcall*)(std::uintptr_t)>(handleOf)(player);
    if (!owner) return identity;
    identity.owner = *owner;
    identity.player = player;
    identity.studio = At<std::uintptr_t>(player,CurrentState().side == Side::Client
        ? kPlayerStudioOffset : kServerPlayerStudioOffset);
    if (!identity.studio) return identity;
    identity.raw = At<std::uintptr_t>(identity.studio,8);
    identity.virtualModel = At<std::uintptr_t>(identity.studio,16);
    if (identity.raw)
    {
        identity.checksum = At<std::uint32_t>(identity.raw,8);
        identity.length = At<int>(identity.raw,76);
    }
    if (identity.virtualModel)
    {
        identity.sequences = At<int>(identity.virtualModel,64);
        identity.groups = At<int>(identity.virtualModel,192);
    }
    return identity;
}

// Side-specific native class predicates reject props/ragdolls that reuse one of the supported pilot
// models, then reject titan players before any player-only model offset is used.
bool IsPilotPlayer(std::uintptr_t player) noexcept
{
    using Predicate = bool(__fastcall*)(std::uintptr_t);
    const auto table = player ? At<std::uintptr_t>(player,0) : 0;
    if (!table || !CurrentState().base) return false;
    if (CurrentState().side == Side::Client)
    {
        const auto isPlayer = At<std::uintptr_t>(table,0x538);
        const auto isTitan = At<std::uintptr_t>(table,0x540);
        return isPlayer && isTitan && reinterpret_cast<Predicate>(isPlayer)(player)
            && !reinterpret_cast<Predicate>(isTitan)(player)
            && !reinterpret_cast<Predicate>(CurrentState().base+kPlayerPredicateRva)(player);
    }
    const auto isPlayer = At<std::uintptr_t>(table,kServerPlayerVtableIsPlayerOffset);
    const auto isTitan = At<std::uintptr_t>(table,kServerPlayerVtableIsTitanOffset);
    return isPlayer && isTitan && reinterpret_cast<Predicate>(isPlayer)(player)
        && !reinterpret_cast<Predicate>(isTitan)(player)
        && !reinterpret_cast<Predicate>(CurrentState().base+kServerPlayerPredicateRva)(player);
}

void ValidateChains(const ModelView& model, const unsigned (*links)[3])
{
    if (model.Read<int>(284) != 2) Fail("required pose must own exactly two native hand IK chains");
    const int chainOffset = model.Read<int>(288);
    model.Span(chainOffset,2,16);
    constexpr std::string_view names[]{"hand_right","hand_left"};
    for (unsigned chain = 0; chain != 2; ++chain)
    {
        const std::size_t at = chainOffset+16*chain;
        if (model.RelativeString(at) != names[chain] || model.Read<int>(at+8) != 3)
            Fail("required pose IK chain identity differs from native release-rule indices");
        const auto linkOffset = static_cast<std::int64_t>(at)+model.Read<int>(at+12);
        model.Span(linkOffset,3,28);
        for (unsigned link = 0; link != 3; ++link)
            if (model.Read<int>(linkOffset+28*link) != static_cast<int>(links[chain][link]))
                Fail("required pose IK link hierarchy differs from authored hand chain");
    }
}

void DestroySource() noexcept
{
    if (CurrentState().sourceConstructed && CurrentState().base)
        Call<void>({kSourceDestroyRva,kServerSourceDestroyRva},static_cast<void*>(CurrentState().sourceHeader));
    CurrentState().sourceConstructed = false;
    std::vector<std::byte>().swap(CurrentState().sourceBytes);
    std::vector<std::byte>().swap(CurrentState().includeBytes);
}

// Reads and pins both slide assets through the GAME filesystem and constructs the native source
// header the evaluator accumulates the 190-bone slide sequences into. Hash/format mismatches reject
// the session permanently; an unmounted filesystem only delays admission.
void EnsureAssets()
{
    if (CurrentState().assets == AssetState::Ready && CurrentState().sourceConstructed) return;
    if (CurrentState().assets == AssetState::Rejected) Fail("pinned slide assets were rejected for this session");
    if (GetTickCount64() < CurrentState().assetRetryAt) Unavailable("pinned slide asset read is cooling down");
    try
    {
        DestroySource();
        auto sourceBytes = ReadPinned(PilotSourceModelPath,PilotSourceModelSha256);
        auto includeBytes = ReadPinned(PilotIncludeModelPath,PilotIncludeModelSha256);
        const ModelView source(sourceBytes.data(),sourceBytes.size());
        source.Validate(SourceBones,SourceBoneCount,nullptr);
        ValidateChains(source,SourceChainLinks);
        if (ModelName(source) != std::string_view(PilotSourceModelPath).substr(7) || source.Read<int>(188) != 8
            || source.Read<int>(180) != 22 || source.Read<int>(300) != 17
            || source.Read<int>(336) || source.Read<int>(352))
            Fail("full source pose asset lost its genuine sequence/parameter closure");
        const ModelView include(includeBytes.data(),includeBytes.size());
        include.Validate(SourceBones,SourceBoneCount,nullptr);
        ValidateChains(include,SourceChainLinks);
        if (ModelName(include) != std::string_view(PilotIncludeModelPath).substr(7) || include.Read<int>(188) != 8
            || include.Read<int>(180) != 22 || include.Read<int>(300) != 2
            || include.Read<int>(336) || include.Read<int>(352))
            Fail("slide include asset lost its exact closed animation graph");
        CurrentState().sourceBytes = std::move(sourceBytes);
        CurrentState().includeBytes = std::move(includeBytes);
        if (CurrentState().side == Side::Client)
            Call<void>({kSourceConstructRva,0},static_cast<void*>(CurrentState().sourceHeader),
                static_cast<const void*>(CurrentState().sourceBytes.data()),static_cast<void*>(nullptr));
        else
        {
            Call<void>({0,kServerSourceHeaderInitRva},static_cast<void*>(CurrentState().sourceHeader));
            Call<void>({0,kServerSourceConstructRva},static_cast<void*>(CurrentState().sourceHeader),
                static_cast<const void*>(CurrentState().sourceBytes.data()),static_cast<void*>(nullptr));
        }
        CurrentState().sourceConstructed = true;
        if (At<std::uintptr_t>(CurrentState().sourceHeader,8) != reinterpret_cast<std::uintptr_t>(CurrentState().sourceBytes.data())
            || At<std::uintptr_t>(CurrentState().sourceHeader,16))
            Fail("owned full source native header acquired unexpected virtual/cache ownership");
        CurrentState().assets = AssetState::Ready;
    }
    catch (const PoseError& error)
    {
        DestroySource();
        if (error.transient)
        {
            CurrentState().assetRetryAt = GetTickCount64() + 5000;
        }
        else
        {
            CurrentState().assets = AssetState::Rejected;
        }
        Report(error.message);
        throw;
    }
}

std::uintptr_t Sequence(std::uintptr_t studio, int sequence)
{
    return Call<std::uintptr_t>({kSequenceRva,kServerSequenceRva},studio,sequence);
}
std::uintptr_t PoseDescriptor(std::uintptr_t studio, int pose)
{
    return Call<std::uintptr_t>({kPoseDescriptorRva,kServerPoseDescriptorRva},studio,pose);
}
bool EqualName(std::string_view a, std::string_view b)
{
    if (a.size() != b.size()) return false;
    for (std::size_t i = 0; i != a.size(); ++i)
    {
        const auto lower = [](char c) { return c >= 'A' && c <= 'Z' ? c-'A'+'a' : c; };
        if (lower(a[i]) != lower(b[i])) return false;
    }
    return true;
}
// The native include owner must be the pinned pilot_slide.mdl generation: same studio length,
// checksum and name as the SHA-verified GAME bytes, plus the exact authored skeleton/chain/graph
// contract checked by the caller.
void RequirePinnedInclude(const ModelView& owner)
{
    const ModelView pinned(CurrentState().includeBytes.data(),CurrentState().includeBytes.size());
    if (owner.Size() != pinned.Size() || owner.Read<std::uint32_t>(8) != pinned.Read<std::uint32_t>(8)
        || ModelName(owner) != ModelName(pinned))
        Fail("native pose include is not the pinned pilot_slide.mdl generation");
}

void Admit(PoseClosure& closure, const ModelIdentity& identity)
{
    const auto root = FindRoot(identity.raw);
    if (!root) Fail("player model is not one of the transferred pilot roots");
    const auto target = RawModel(identity.raw);
    const Profile* profile = Marker(target);
    if (!profile || profile != root->profile) Fail("player model pose marker does not match its authored profile");
    target.Validate(profile->targetBones,profile->targetCount,profile->targetPoseToBone);
    ValidateChains(target,profile->chainLinks);
    const int includeCount = target.Read<int>(336), includeOffset = target.Read<int>(340);
    if (includeCount != 7) Fail("player pose include declarations changed");
    target.Span(includeOffset,includeCount,8);
    if (target.RelativeString(includeOffset+8*(includeCount-1),4) != PilotIncludeModelPath)
        Fail("pilot slide include identity changed");
    if (!CurrentState().sourceConstructed || CurrentState().assets != AssetState::Ready) Fail("pinned slide assets are not prepared");
    closure.profile = profile;
    if (!identity.virtualModel) Fail("player model has no native include graph");
    const auto vm = identity.virtualModel;
    const int count = At<int>(vm,64), groups = At<int>(vm,192);
    const int poses = Call<int>({kPoseCountRva,kServerPoseCountRva},identity.studio);
    if (count <= 0 || count > 65535 || groups != 8 || poses != static_cast<int>(profile->poseCount))
        Fail("native virtual sequence/group/pose closure differs from admitted assets");
    const auto entries = At<std::uintptr_t>(vm,40);
    const auto groupArray = At<std::uintptr_t>(vm,168);
    if (!entries || !groupArray) Fail("native virtual model has absent mapping arrays");
    closure.sourceSequence.assign(static_cast<std::size_t>(count),-1);
    closure.sourceGroup = -1;
    unsigned sourceMask = 0;
    const ModelView source(CurrentState().sourceBytes.data(),CurrentState().sourceBytes.size());
    for (int i = 0; i != count; ++i)
    {
        const auto entry = entries+16*i;
        const int group = At<int>(entry,8), local = At<int>(entry,12);
        if (group < 0 || group >= groups || local < 0) Fail("invalid native virtual sequence identity");
        const auto desc = Sequence(identity.studio,i);
        if (!desc) Fail("native sequence resolver returned no descriptor");
        const auto owner = RawModel(desc+At<int>(desc,0));
        if (local >= owner.Read<int>(188) || desc != reinterpret_cast<std::uintptr_t>(
            owner.Span(static_cast<std::int64_t>(owner.Read<int>(192))+212LL*local,1,212)))
            Fail("native virtual sequence does not belong to its declared local owner");
        if (ModelName(owner) != std::string_view(PilotIncludeModelPath).substr(7)) continue;
        RequirePinnedInclude(owner);
        if (local >= 8 || (sourceMask & (1u<<local))
            || (closure.sourceGroup != -1 && closure.sourceGroup != group))
            Fail("source slide sequence ownership is duplicated or split across groups");
        if (closure.sourceGroup == -1)
        {
            owner.Validate(SourceBones,SourceBoneCount,nullptr);
            ValidateChains(owner,SourceChainLinks);
            if (owner.Read<int>(188) != 8 || owner.Read<int>(180) != 22 || owner.Read<int>(300) != 2
                || owner.Read<int>(336) || owner.Read<int>(352))
                Fail("native slide include no longer has its exact closed animation graph");
            closure.sourceGroup = group;
            const auto object = groupArray+232*group;
            const auto forward = At<std::uintptr_t>(object,40), reverse = At<std::uintptr_t>(object,8);
            const auto poseMap = At<std::uintptr_t>(object,168);
            if (!forward || !reverse || !poseMap) Fail("native source group mapping arrays are absent");
            for (unsigned bone = 0; bone != SourceBoneCount; ++bone)
                if (At<int>(forward,4*bone) != profile->mappings[bone].target
                    || At<int>(reverse,4*profile->mappings[bone].target) != static_cast<int>(bone))
                    Fail("native source bone maps differ from all190 authored mappings");
            for (unsigned axis = 0; axis != 2; ++axis)
            {
                const int mapped = At<int>(poseMap,4*axis);
                if (mapped < 0 || mapped >= poses) Fail("source aim axis exceeds actual native pose storage");
                closure.poseIndices[axis] = mapped;
                const auto effective = PoseDescriptor(identity.studio,mapped);
                const auto* poseName = reinterpret_cast<const char*>(effective+At<int>(effective,0));
                const auto at = source.Read<int>(304)+20*axis;
                const auto expected = source.RelativeString(at);
                // Native descriptors are cache-owned, not file-bounded. Their
                // producer-admitted names are checked without unbounded strlen.
                if (!EqualName(std::string_view(poseName,expected.size()),expected)
                    || poseName[expected.size()] || At<int>(effective,4) || At<float>(effective,16)
                    || !std::isfinite(At<float>(effective,8)) || !std::isfinite(At<float>(effective,12))
                    || !(At<float>(effective,8) < At<float>(effective,12)))
                    Fail("effective native aim descriptor has incompatible physical semantics");
            }
            if (closure.poseIndices[0] == closure.poseIndices[1]) Fail("native aim axes are aliased");
        }
        const auto targetAt = owner.Read<int>(192)+212*local;
        const auto sourceAt = source.Read<int>(192)+212*local;
        if (owner.RelativeString(targetAt,4) != source.RelativeString(sourceAt,4)
            || owner.RelativeString(targetAt,8) != source.RelativeString(sourceAt,8)
            || owner.Read<int>(targetAt+144) != source.Read<int>(sourceAt+144)
            || owner.Read<int>(targetAt+148) != source.Read<int>(sourceAt+148)
            || owner.Read<int>(targetAt+164))
            Fail("native slide descriptor differs from source sequence/layer/release identity");
        closure.sourceSequence[i] = local;
        sourceMask |= 1u<<local;
    }
    if (sourceMask != 255) Fail("native include closure omitted source slide sequences");
    if (CurrentState().side == Side::Client
        && At<std::uintptr_t>(At<std::uintptr_t>(identity.player,0),kBoundaryVtableOffset)
            != CurrentState().base+kBoundaryRva)
        Fail("client player class lacks the proven pre-external gesture boundary");
}

thread_local struct Invocation* t_current{};
thread_local State* t_currentState{};

// Returns the admitted closure for the player's current model, or null to decline. Caller holds
// the shared pose mutex; negative results are cached per model identity.
PoseClosure* AdmittedClosure(std::uintptr_t player, std::uintptr_t studio) noexcept
{
    try
    {
        if (!CurrentState().ready.load(std::memory_order_acquire) || !IsPilotPlayer(player)) return nullptr;
        const ModelIdentity identity = CurrentModel(player);
        if (!identity.studio || (studio && studio != identity.studio) || !FindRoot(identity.raw))
            return nullptr;
        const auto found = CurrentState().closures.find(identity.studio);
        if (found != CurrentState().closures.end() && found->second.session == CurrentState().session && found->second.model == identity)
            return found->second.admitted && !found->second.disabled ? &found->second : nullptr;
        // Never re-admit while an evaluation on this thread owns a closure.
        if (t_currentState == &CurrentState()) return nullptr;
        EnsureAssets();
        if (CurrentState().closures.size() >= 128) CurrentState().closures.clear();
        PoseClosure& closure = CurrentState().closures[identity.studio];
        closure = PoseClosure{};
        closure.model = identity;
        closure.session = CurrentState().session;
        closure.generation = ++CurrentState().generation;
        try
        {
            Admit(closure,identity);
            closure.admitted = true;
            return &closure;
        }
        catch (const PoseError& error)
        {
            closure.admitted = false;
            Report(error.message);
            return nullptr;
        }
    }
    catch (...)
    {
        return nullptr;
    }
}

struct Invocation
{
    State& state;
    PoseClosure& closure;
    std::uintptr_t entity, studio;
    PoseChannels target;
    Invocation* previous;
    State* previousState;
    NativeSetup setup;
    NativeSetup* wrapper{&setup};
    alignas(16) float positions[TargetBoneCapacity][3], quaternions[TargetBoneCapacity][4], scales[TargetBoneCapacity][3];
    float parameters[24]{};
    bool started{}, finished{}, failed{};
    Invocation(State& owner, PoseClosure& c, std::uintptr_t player, std::uintptr_t header, void* p, void* q, void* s)
        : state(owner), closure(c), entity(player), studio(header),
          target{static_cast<float(*)[3]>(p),static_cast<float(*)[4]>(q),static_cast<float(*)[3]>(s)},
          previous(t_current), previousState(t_currentState)
    {
        t_current = this;
        t_currentState = &state;
        CurrentState().frames.fetch_add(1,std::memory_order_acq_rel);
    }
    Invocation(const Invocation&) = delete;
    Invocation& operator=(const Invocation&) = delete;
    ~Invocation()
    {
        // The internal NONFREEING native destructor, never the wrapper destructor.
        if (started) Call<void>({kSetupDestroyRva,kServerSetupDestroyRva},&setup);
        t_current = previous;
        t_currentState = previousState;
        CurrentState().frames.fetch_sub(1,std::memory_order_acq_rel);
    }
    PoseChannels Source() { return {positions,quaternions,scales}; }
    // A faulted frame stops touching the pose, leaves native channels as last committed, and
    // disables the model until its identity changes.
    void Fault(const char* message) noexcept
    {
        if (!failed)
        {
            failed = true;
            closure.disabled = true;
            Report(message);
        }
    }
    void Begin(const NativeSetup& native)
    {
        if (started) return;
        if (native.observer || native.skip > 1 || native.face > 1)
            Fail("required complete pose has unsupported native observer or LOD flags");
        setup.header = reinterpret_cast<std::uintptr_t>(CurrentState().sourceHeader);
        setup.bones = &FullSource;
        setup.cacheCount = 0;
        setup.poses = parameters;
        setup.observer = nullptr;
        setup.face = native.face;
        setup.skip = native.skip;
        // Exactly the native 1328B constructor stores; unused cache entries remain uninitialized
        // until native accumulation owns them.
        started = true;
        if (CurrentState().side == Side::Client)
            Call<void>({kSetupConstructRva,0},&wrapper,positions,quaternions,scales);
        else
            Call<void>({0,kServerSetupConstructRva},setup.header,positions,quaternions,scales,&FullSource);
        ImportNativePose(*closure.profile,target,Source());
    }
    void Parameters(const NativeSetup& native)
    {
        if (!native.poses) Fail("native player pose controls are absent");
        for (unsigned axis = 0; axis != 2; ++axis)
        {
            const auto desc = PoseDescriptor(studio,closure.poseIndices[axis]);
            const float fraction = native.poses[closure.poseIndices[axis]];
            const float start = At<float>(desc,8), end = At<float>(desc,12);
            if (!std::isfinite(fraction) || !std::isfinite(start) || !std::isfinite(end) || !(start < end)
                || At<int>(desc,4) || At<float>(desc,16))
                Fail("effective canonical native pose range changed physical semantics");
            // Read the ACTUAL mutable canonical range, then use the genuine full17 source normalizer.
            const float physical = (end-start)*fraction+start;
            Call<float>({kPitchNormalizeRva,kServerPitchNormalizeRva},setup.header,
                static_cast<int>(axis),physical,&parameters[axis]);
            if (!std::isfinite(parameters[axis])) Fail("source physical pose normalization failed");
        }
    }
    void Finish() noexcept
    {
        if (finished) { Fault("native complete-pose boundary executed twice"); return; }
        finished = true;
        if (!started || failed) return;
        try { RetargetCompletePose(*closure.profile,Source(),target); }
        catch (const PoseError& error) { Fault(error.message); }
        catch (...) { Fault("unexpected failure retargeting the complete pose"); }
    }
};

void AccumulateImpl(void* setupArgument, void* p, void* q, void* s, int sequence, float cycle,
    float weight, float time, void* ik, std::uintptr_t caller)
{
    const auto original = [&] { CurrentState().accumulate(setupArgument,p,q,s,sequence,cycle,weight,time,ik); };
    Invocation* frame = CurrentState().frames.load(std::memory_order_relaxed) ? t_current : nullptr;
    if (!frame || &frame->state != &CurrentState() || !setupArgument) { original(); return; }
    auto* native = CurrentState().side == Side::Client
        ? *static_cast<NativeSetup**>(setupArgument) : static_cast<NativeSetup*>(setupArgument);
    if (!native || native->header != frame->studio || frame->target.position != p
        || frame->target.quaternion != q || frame->target.scale != s)
    {
        original();
        return;
    }
    PoseClosure& closure = frame->closure;
    if (sequence < 0 || static_cast<std::size_t>(sequence) >= closure.sourceSequence.size())
    {
        original();
        return;
    }
    const int source = closure.sourceSequence[sequence];
    const auto rva = caller - CurrentState().base;
    const bool scheduled = CurrentState().side == Side::Client
        ? (rva == kScheduledReturnA || rva == kScheduledReturnB)
        : (rva == kServerScheduledReturnA || rva == kServerScheduledReturnB);
    if (!scheduled)
    {
        original();
        return;
    }
    // Native decides for non-source layers; a source slide is skipped only after the frame already
    // owns source state, otherwise the stock accumulate runs (declined, unretargeted).
    const bool nativeFallback = source < 0 || !frame->started;
    if (frame->failed) { if (nativeFallback) original(); return; }
    if (frame->finished || native->bones != &closure.profile->fullTarget || native->observer
        || !std::isfinite(cycle) || !std::isfinite(weight) || !std::isfinite(time))
    {
        frame->Fault("native scheduled pose changed complete-pose ownership");
        if (nativeFallback) original();
        return;
    }
    if (source < 0)
    {
        if (frame->started)
        {
            try { RetargetCompletePose(*closure.profile,frame->Source(),frame->target); }
            catch (const PoseError& error) { frame->Fault(error.message); }
            catch (...) { frame->Fault("unexpected failure retargeting the complete pose"); }
        }
        original(); // Preserve every actual foreign operator/bookkeeping once.
        if (frame->started && !frame->failed)
        {
            try { ImportNativePose(*closure.profile,frame->target,frame->Source()); }
            catch (const PoseError& error) { frame->Fault(error.message); }
            catch (...) { frame->Fault("unexpected failure importing the native pose"); }
        }
        return;
    }
    bool completed = false;
    try
    {
        frame->Begin(*native);
        frame->Parameters(*native);
        // These are native view/distance LOD controls, not ownership markers.
        frame->setup.face = native->face;
        frame->setup.skip = native->skip;
        void* sourceArgument = CurrentState().side == Side::Client
            ? static_cast<void*>(&frame->wrapper) : static_cast<void*>(&frame->setup);
        CurrentState().accumulate(sourceArgument,frame->positions,frame->quaternions,
            frame->scales,source,cycle,weight,time,nullptr);
        // The source operations carry no IK of their own; a null native IK context is native
        // IK-disabled semantics. Otherwise register the TARGET at this exact ordered operation.
        if (source != 1 && ik)
        {
            if (At<std::uintptr_t>(ik,0x1508) != frame->studio)
                Fail("native IK context belongs to another pose header");
            Call<void>({kIkRegisterRva,kServerIkRegisterRva},ik,Sequence(frame->studio,sequence),
                sequence,cycle,native->poses,std::clamp(weight,0.0f,1.0f));
        }
        completed = true;
    }
    catch (const PoseError& error) { frame->Fault(error.message); }
    catch (...) { frame->Fault("unexpected failure accumulating the source slide"); }
    if (!completed && !frame->started) original();
}

void __fastcall AccumulateHook(void* setupArgument, void* p, void* q, void* s,
    int sequence, float cycle, float weight, float time, void* ik)
{
    StateScope active(gClient);
    AccumulateImpl(setupArgument,p,q,s,sequence,cycle,weight,time,ik,
        reinterpret_cast<std::uintptr_t>(_ReturnAddress()));
}

void __fastcall ServerAccumulateHook(void* setupArgument, void* p, void* q, void* s,
    int sequence, float cycle, float weight, float time, void* ik)
{
    StateScope active(gServer);
    AccumulateImpl(setupArgument,p,q,s,sequence,cycle,weight,time,ik,
        reinterpret_cast<std::uintptr_t>(_ReturnAddress()));
}

void __fastcall BoundaryHook(std::uintptr_t entity, void* wrapper, void* p, void* q, void* s, float time)
{
    StateScope active(gClient);
    if (CurrentState().frames.load(std::memory_order_relaxed))
    {
        Invocation* frame = t_current;
        if (frame && &frame->state == &CurrentState() && frame->entity == entity
            && reinterpret_cast<std::uintptr_t>(_ReturnAddress()) == CurrentState().base+kBoundaryReturn)
            frame->Finish();
    }
    reinterpret_cast<ClientBoundary>(CurrentState().boundary)(entity,wrapper,p,q,s,time);
}

void __fastcall ServerBoundaryHook(std::uintptr_t entity, void* wrapper, void* p, void* q, void* s)
{
    StateScope active(gServer);
    const auto caller = reinterpret_cast<std::uintptr_t>(_ReturnAddress());
    reinterpret_cast<ServerBoundary>(CurrentState().boundary)(entity,wrapper,p,q,s);
    if (CurrentState().frames.load(std::memory_order_relaxed))
    {
        Invocation* frame = t_current;
        if (frame && &frame->state == &CurrentState() && frame->entity == entity
            && caller == CurrentState().base+kServerBoundaryReturn)
            frame->Finish();
    }
}

void __fastcall OuterHook(std::uintptr_t entity, std::uintptr_t studio,
    void* p, void* q, void* s, float time, const BoneList* bones)
{
    StateScope active(gClient);
    const auto original = reinterpret_cast<ClientOuter>(CurrentState().outer);
    if (!CurrentState().ready.load(std::memory_order_acquire) || !FindRootForStudio(studio))
    {
        original(entity,studio,p,q,s,time,bones);
        return;
    }
    {
        std::lock_guard<std::recursive_mutex> lock(CurrentState().mutex);
        PoseClosure* closure = AdmittedClosure(entity,studio);
        if (closure)
        {
            Invocation frame(CurrentState(),*closure,entity,studio,p,q,s);
            original(entity,studio,p,q,s,time,&closure->profile->fullTarget);
            if (frame.started && !frame.finished)
            {
                closure->disabled = true;
                Report("client source pose missed its pre-gesture boundary");
                frame.Finish();
            }
            return;
        }
    }
    original(entity,studio,p,q,s,time,bones);
}

void __fastcall ServerOuterHook(std::uintptr_t entity, std::uintptr_t studio,
    void* p, void* q, void* s, const BoneList* bones)
{
    StateScope active(gServer);
    const auto original = reinterpret_cast<ServerOuter>(CurrentState().outer);
    if (!CurrentState().ready.load(std::memory_order_acquire) || !FindRootForStudio(studio))
    {
        original(entity,studio,p,q,s,bones);
        return;
    }
    {
        std::lock_guard<std::recursive_mutex> lock(CurrentState().mutex);
        PoseClosure* closure = AdmittedClosure(entity,studio);
        if (closure)
        {
            Invocation frame(CurrentState(),*closure,entity,studio,p,q,s);
            original(entity,studio,p,q,s,&closure->profile->fullTarget);
            if (frame.started && !frame.finished)
            {
                closure->disabled = true;
                Report("server source pose missed its pre-external boundary");
                frame.Finish();
            }
            return;
        }
    }
    original(entity,studio,p,q,s,bones);
}

